import { Empty, Button } from "march/ui"

// boş tabak: emojili boş durum; "Yemek ekle" tabağı doldurur, "Bitir" yeniden boşaltır
const FOODS = ["🍕", "🥗", "🍜", "🌮", "🍰"]

export function EmptyPlate() {
  let $plate: string[] = []
  return <div sx={{ flex: "col", gap: 2 }}>
    {() => $plate.length
      ? <div sx={{ flex: ["row", "wrap"], gap: 2, text: "xl" }}>
          {$plate.join(" ")}
          <Button size="sm" variant="ghost" on:click={() => $plate = []}>Bitir</Button>
        </div>
      : <Empty icon="🍽️" title="Tabak bomboş" action={<Button variant="primary" on:click={() => $plate = [...$plate, FOODS[0]!]}>Yemek ekle</Button>}>
          Acıktıysanız bir şeyler ekleyin.
        </Empty>}
    {() => $plate.length > 0 && $plate.length < FOODS.length
      ? <Button size="sm" on:click={() => $plate = [...$plate, FOODS[$plate.length]!]}>Bir tane daha</Button> : null}
  </div>
}

import { Empty, Button, Card } from "march/ui"
import { search, x } from "march/icons"

// bir arama sayfası: sonuç yoksa küçük (sm) boş durum ve aramayı temizleyen düğme
const CITIES = ["Ankara", "İstanbul", "İzmir", "Bursa", "Antalya", "Eskişehir"]

export function SearchResults() {
  let $q = "Paris"
  const hits = () => CITIES.filter((c) => c.toLocaleLowerCase("tr").includes($q.toLocaleLowerCase("tr")))
  return <Card title="Şehir ara">
    <input class="m-input" aria-label="Şehir" placeholder="Şehir adı" value={() => $q} on:input={(e: Event) => $q = (e.target as HTMLInputElement).value} />
    {() => hits().length
      ? <ul>{hits().map((c) => <li>{c}</li>)}</ul>
      : <Empty size="sm" icon={search} title={`"${$q}" için sonuç yok`}
          action={<Button size="sm" icon={x} on:click={() => $q = ""}>Aramayı temizle</Button>}>
          Yazımı kontrol edin ya da başka bir şehir deneyin.
        </Empty>}
  </Card>
}

import { test, expect, renderTest } from "march/testing"
import { EmptyLab } from "./EmptyLab.tsx"

// EmptyLab'in testleri: kaydedince Testler sekmesinde çalışır
test("title verilmezse varsayılan başlık, title={false} başlığı kaldırır", () => {
  const s = renderTest(() => <EmptyLab />)
  const titles = s.all(".m-empty-title").map((e: Element) => e.textContent)
  expect(titles.length).toBe(4)
  expect(s.find("Başlıksız; ikon kendi düğümüm.")?.closest(".m-empty")?.querySelector(".m-empty-title")).toBe(null)
})

test("action() nesnesi düğme olur; basınca başlık erişimcisi güncellenir", async () => {
  const s = renderTest(() => <EmptyLab />)
  await s.click("Davet et")
  await s.flush()
  expect(s.sees("Davet edilen: 1")).toBe(true)
})

test("size=sm ve class köke eklenir; kendi düğüm olduğu gibi çizilir", () => {
  const s = renderTest(() => <EmptyLab />)
  const e = s.get(".lab-empty")
  expect(e?.classList.contains("m-empty-sm")).toBe(true)
  expect(s.get(".lab-art")?.textContent).toBe("🌵")
})
